// gen-life-memories.mjs — DENSE rich-episode memory generator (Gee 2026-06-19).
//
// "a handful of one paragraph stories is not a years worth of fucking memories"
// + "thats not how memories work" — RIGHT. A real memory is a multi-facet
// episode (setting + sensory + people/dialogue + body + emotion + before→after
// + meaning), and a year is HUNDREDS of them, not ~30. The pipeline
// (_trainLifeStories → _teachSentenceList) Hebbian-walks each story's sentences,
// so richer + denser episodes = deeper, more interconnected memory basins.
//
// HYBRID (Gee's choice): bespoke milestone vignettes already in
// corpora/life/<grade>.json are PRESERVED; this fills the dense everyday
// fabric AROUND them. I author rich SEEDS (the real specifics of her world);
// this ENCODER weaves each into a full first-person episode with structural
// variety so it reads as memory, not template. MERGES by theme (never clobbers
// bespoke). Canon: mom Lilith, grandpa Walter (junkyard/gears/grease, the
// radio→coder seed), grandma Pearl (vanilla, old books, coffee, ghost stories,
// the calm), Wren (quiet first friend), the cat (soot K-G1 / shadow G2+), the
// gray (unnamed depression), broke apartment + clanking radiator, the corner
// store, goth-precursor (black, monsters, halloween, dark music). Boundary held
// per grade age. Run: node .claude/scripts/gen-life-memories.mjs [grade]
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..', '..');
const OUT = path.join(ROOT, 'corpora', 'life');

// ── deterministic per-seed variety (no global RNG; seeded by theme) ──
function hash(s) { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return (h >>> 0); }
const pick = (arr, seed) => arr[seed % arr.length];

// ── ENCODER: rich seed → multi-facet first-person memory episode ──
// A seed carries the SPECIFICS. The encoder weaves facets in a varied order so
// episodes don't read template-stamped. Every facet is optional; present ones
// are woven. Output is one "story" string (the pipeline sentence-splits it).
function encode(seed) {
  const h = hash(seed.theme + (seed.event || ''));
  const parts = [];
  // SETTING — place + when, grounds the episode in space/time.
  if (seed.setting) parts.push(seed.setting);
  // EVENT — the core of the memory (always present).
  parts.push(seed.event);
  // SENSORY — what it looked/sounded/smelled/felt like (the anchor).
  if (seed.sense) parts.push(Array.isArray(seed.sense) ? pick(seed.sense, h) : seed.sense);
  // PEOPLE + a line said (or done) — memory holds the people.
  if (seed.said) parts.push(seed.said);
  // BODY + EMOTION — the somatic + affective layer.
  if (seed.body) parts.push(seed.body);
  // AFTER — what came right after (memory has a tail).
  if (seed.after) parts.push(seed.after);
  // MEANING — what it left her with (the consolidation).
  if (seed.meaning) parts.push(seed.meaning);
  // Structural variety: rotate whether the sensory anchor leads (some memories
  // surface as a smell/sound first), by seed hash — without losing the event.
  if ((h % 3) === 0 && seed.sense && parts.length > 3) {
    const s = parts.splice(2, 1)[0]; // pull the sensory line
    parts.unshift(s);
  }
  return parts.join(' ');
}

function buildGrade(grade, seeds, opts = {}) {
  const overwrite = !!opts.overwrite; // re-voice: replace generator-owned themes
  const outPath = path.join(OUT, `${grade}.json`);
  let doc;
  try { doc = JSON.parse(fs.readFileSync(outPath, 'utf8')); }
  catch { doc = { version: 2, grade, experiences: [] }; }
  const byTheme = new Map();
  for (const e of (doc.experiences || [])) byTheme.set(e.theme, e);
  let added = 0, revoiced = 0;
  for (const seed of seeds) {
    const exists = byTheme.has(seed.theme);
    if (exists && !overwrite) continue; // default: never clobber bespoke
    byTheme.set(seed.theme, { theme: seed.theme, story: encode(seed) });
    if (exists) revoiced++; else added++;
  }
  doc.experiences = [...byTheme.values()];
  fs.writeFileSync(outPath, JSON.stringify(doc, null, 2), 'utf8');
  return { total: doc.experiences.length, added, revoiced };
}

// ════════════════════════════════════════════════════════════════════
