const args = process.argv.slice(2);
const overwrite = args.includes('--overwrite');
const gradeArg = args.find(a => !a.startsWith('--'));
let totalAdded = 0, totalRevoiced = 0;
for (const grade of Object.keys(SEEDS)) {
  if (gradeArg && grade !== gradeArg) continue;
  const r = buildGrade(grade, SEEDS[grade], { overwrite });
  console.log(`[life-mem] ${grade}: +${r.added} new · ${r.revoiced} re-voiced → ${r.total} total`);
  totalAdded += r.added; totalRevoiced += r.revoiced;
}
console.log(`[life-mem] DONE — +${totalAdded} new, ${totalRevoiced} re-voiced (bespoke preserved unless --overwrite).`);
